"""Clinical mode 'Administer System' functions. These functions are called from the top level
IntegrityService interface. They are not intended to be called directly from a test script"""

import interops.libraries.integrity.pages.clinical_screen as ClinicalPgObj
from typing import Optional as opt
from typing import Dict

def _open_customize_system_settings_page() -> bool:
    '''
    Selects the Administer System button followed by the Customize System Settings button
    '''
    menu = ClinicalPgObj.ClinicalMenuBar()
    if menu.ready():
        menu.administer_system_customize_system_settings()
        customize_sys_settings_pg_obj = ClinicalPgObj.CustomizeSystemSettings()
        return customize_sys_settings_pg_obj.ready()
    return False

def _select_tolerance_tables_tab() -> None:
    '''
    Opens the Customize System Settings page in clinical mode

    Returns:
        bool - True if Customize System Settings page opened
    '''
    if _open_customize_system_settings_page():
        customize_sys_settings_pg_obj = ClinicalPgObj.CustomizeSystemSettings()
        customize_sys_settings_pg_obj.select_tolerances_table_tab()


def _read_tolerance_geometric_param_value(tolerance_table: str, get_geometric_parameter: str) -> opt[str]:
    '''
    Selects the tolerance tables tab if not already opened, selects the specified tolerance table
    from the list and returns the requested geometric parameter value as a string.

    Args:
        tolerance_table (str): Tolerance table name to select from the list.
                                    Can be "XRAY", "ELECTRON", "SERVICE 1" or "ICOM"

        get_geometric_parameter (str): Name of geometric parameter to read value from.
                                       Geometric parameter can be one of the following:
                                       "Diaphragm Y2", "Diaphragm Y1", "Diaphragm X2",
                                       "Diaphragm X1", "Fieldsize X", "Fieldsize Y",
                                       "Field Offset X", "Field Offset Y", "Collimator Angle",
                                       "Gantry Angle", "Table Vertical", "Table Lateral",
                                       "Table Longitudinal", "Column Rotation", "Isocentric Rotation"

    Returns:
        str or None: Geometric parameter value or None if not found
    '''
    customize_sys_settings_pg_obj = ClinicalPgObj.CustomizeSystemSettings()
    if not customize_sys_settings_pg_obj.tolerance_tables_pane_ready():
        _select_tolerance_tables_tab()
    customize_sys_settings_pg_obj.select_tolerance_table_name_from_list(tolerance_table)
    geo_param = customize_sys_settings_pg_obj.get_tolerance_geometric_parameter_value(get_geometric_parameter)
    return geo_param


def _set_tolerance_geometric_param_value(tolerance_table: str, geometric_param_set_values: Dict[str, str]) -> bool:
    '''
    Selects the tolerance tables tab if not already opened, selects the specified tolerance table
    from the list and sets new geometric parameter value(s) from the dictionary. Selects the Save
    button and confirms the customisation change.

    Args:
        tolerance_table (str): Tolerance table name to select from the list.
                               Can be "XRAY", "ELECTRON", "SERVICE 1" or "ICOM"

        geometric_param_set_values (dict of str: str): Dictionary of geometric parameter
        field name to set string as the key, and string value to set as the value. An example
        dictionary of geometric parameter key, value pairs are as follows:

        set_geometric_params_dict = {"Gantry Angle": "1.5",
                                        "Collimator Angle": "2.0",
                                        "Table Vertical": "3.0",}

        Geometric Parameter Keys can be one of the following strings:
            "Diaphragm Y2", "Diaphragm Y1", "Collimator Angle", "Gantry Angle",
            "Table Vertical", "Table Lateral", "Table Longitudinal", "Column Rotation"

    Returns:
        bool - True if the geometric parameter fields were successfully set, False otherwise
    '''
    customize_sys_settings_pg_obj = ClinicalPgObj.CustomizeSystemSettings()
    if not customize_sys_settings_pg_obj.tolerance_tables_pane_ready():
        _select_tolerance_tables_tab()
    customize_sys_settings_pg_obj.select_tolerance_table_name_from_list(tolerance_table)
    customize_sys_settings_pg_obj.set_tolerance_geometric_parameter_values(geometric_param_set_values)
    # Note: The Save button remains disabled when an invalid geometric parameter value is entered. Return False for this condition.
    if customize_sys_settings_pg_obj.save_and_confirm_geometric_parameter_value_change():
        return True
    return False